//! Phosphor Icons (Regular, 256x256 viewBox), MIT (c) Phosphor Icons.

use rune::{Color, El, Icon};
use studynodes_graph::model::NodeKind;

pub fn ph(i: &'static Icon, size: f32, color: Color) -> El {
    rune::icon(i, size).color(color)
}

pub fn kind_icon(kind: NodeKind) -> &'static Icon {
    match kind {
        NodeKind::Note => &NOTE_PENCIL,
        NodeKind::Text => &TEXT_T,
        NodeKind::Document => &FILE_TEXT,
        NodeKind::Image => &IMAGE,
        NodeKind::LlmSynthesis => &SPARKLE,
        NodeKind::Concept => &LIGHTBULB,
        NodeKind::Section => &FRAME_CORNERS,
        NodeKind::Excerpt => &QUOTES,
        NodeKind::Flashcard => &CARDS,
        NodeKind::Formula => &FUNCTION,
        NodeKind::GraphFormula => &CHART_LINE,
        NodeKind::Checklist => &CHECK_SQUARE,
        NodeKind::Sequence => &FLOW_ARROW,
        NodeKind::Video => &PLAY_CIRCLE,
        NodeKind::Audio => &MUSIC_NOTES,
        NodeKind::Calendar => &CALENDAR_BLANK,
        NodeKind::Drawing => &PENCIL_SIMPLE,
        NodeKind::Quiz => &QUESTION,
    }
}

